import React, { useState, useRef } from 'react';
import { useOffline } from '../contexts/OfflineContext';

const MediaUploader = ({ donorId, onUploadSuccess }) => {
    const [isCapturing, setIsCapturing] = useState(false);
    const [mediaType, setMediaType] = useState('image'); // 'image' or 'video'
    const [preview, setPreview] = useState(null);
    const [uploading, setUploading] = useState(false);
    const [uploadProgress, setUploadProgress] = useState(0);
    const [error, setError] = useState(null);

    const fileInputRef = useRef(null);
    const videoRef = useRef(null);
    const { isOffline, queueMediaUpload } = useOffline();

    // Handle file selection
    const handleFileChange = async (e) => {
        setError(null);
        const file = e.target.files[0];
        if (!file) return;

        // Validate file type
        if (mediaType === 'image' && !file.type.startsWith('image/')) {
            setError('Please select an image file');
            return;
        }

        if (mediaType === 'video' && !file.type.startsWith('video/')) {
            setError('Please select a video file');
            return;
        }

        try {
            // Create preview
            const objectUrl = URL.createObjectURL(file);
            setPreview(objectUrl);

            // Handle upload
            await handleUpload(file);

            // Cleanup preview
            return () => URL.revokeObjectURL(objectUrl);
        } catch (err) {
            setError('Error preparing file');
            console.error(err);
        }
    };

    // Handle camera/video capture
    const startCapture = () => {
        setIsCapturing(true);
        navigator.mediaDevices.getUserMedia({
            video: true,
            audio: mediaType === 'video'
        })
            .then(stream => {
                if (videoRef.current) {
                    videoRef.current.srcObject = stream;
                    videoRef.current.play();
                }
            })
            .catch(err => {
                console.error('Error accessing media devices:', err);
                setError('Could not access camera');
                setIsCapturing(false);
            });
    };

    // Capture image from camera
    const captureImage = () => {
        if (!videoRef.current) return;

        const canvas = document.createElement('canvas');
        canvas.width = videoRef.current.videoWidth;
        canvas.height = videoRef.current.videoHeight;

        const ctx = canvas.getContext('2d');
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);

        // Convert to blob
        canvas.toBlob(async (blob) => {
            // Create a file from the blob
            const file = new File([blob], `photo-${Date.now()}.jpg`, { type: 'image/jpeg' });

            // Create preview
            const objectUrl = URL.createObjectURL(file);
            setPreview(objectUrl);

            // Stop camera
            stopCapture();

            // Handle upload
            await handleUpload(file);
        }, 'image/jpeg');
    };

    // Stop media capture
    const stopCapture = () => {
        if (videoRef.current && videoRef.current.srcObject) {
            videoRef.current.srcObject.getTracks().forEach(track => track.stop());
            videoRef.current.srcObject = null;
        }
        setIsCapturing(false);
    };

    // Handle upload to storage
    const handleUpload = async (file) => {
        setUploading(true);
        setUploadProgress(0);

        try {
            // Simulate upload progress
            const progressInterval = setInterval(() => {
                setUploadProgress(prev => {
                    const newProgress = prev + 10;
                    if (newProgress >= 90) {
                        clearInterval(progressInterval);
                        return 90;
                    }
                    return newProgress;
                });
            }, 200);

            // Store file locally if offline
            const result = await queueMediaUpload(donorId, {
                file: file,
                type: mediaType
            });
            const fileId = result.success ? result.id : null;
            // Complete progress
            clearInterval(progressInterval);
            setUploadProgress(100);

            // Call success callback
            if (onUploadSuccess) {
                onUploadSuccess({
                    fileId,
                    type: mediaType,
                    status: isOffline ? 'pending' : 'uploaded'
                });
            }

            setTimeout(() => {
                setUploading(false);
                setUploadProgress(0);
            }, 1000);
        } catch (err) {
            setError('Upload failed');
            console.error('Upload error:', err);
            setUploading(false);
        }
    };

    return (
        <div className="border-2 border-gray-300 rounded-lg p-4 bg-white">
            <div className="mb-4">
                <div className="flex space-x-2 mb-4">
                    <button
                        type="button"
                        onClick={() => setMediaType('image')}
                        className={`px-4 py-2 rounded-lg ${mediaType === 'image'
                                ? 'bg-blue-600 text-white'
                                : 'bg-gray-200 text-gray-700'
                            }`}
                    >
                        Image
                    </button>
                    <button
                        type="button"
                        onClick={() => setMediaType('video')}
                        className={`px-4 py-2 rounded-lg ${mediaType === 'video'
                                ? 'bg-blue-600 text-white'
                                : 'bg-gray-200 text-gray-700'
                            }`}
                    >
                        Video
                    </button>
                </div>

                {isCapturing ? (
                    <div className="relative">
                        <video
                            ref={videoRef}
                            className="w-full rounded-lg border-2 border-gray-300"
                            autoPlay
                            muted={mediaType === 'image'}
                        />
                        <div className="absolute bottom-3 left-0 right-0 flex justify-center">
                            {mediaType === 'image' ? (
                                <button
                                    type="button"
                                    onClick={captureImage}
                                    className="px-4 py-2 bg-blue-600 text-white rounded-full shadow-lg"
                                >
                                    Capture
                                </button>
                            ) : (
                                <button
                                    type="button"
                                    onClick={stopCapture}
                                    className="px-4 py-2 bg-red-600 text-white rounded-full shadow-lg"
                                >
                                    Stop Recording
                                </button>
                            )}
                        </div>
                    </div>
                ) : preview ? (
                    <div className="relative">
                        {mediaType === 'image' ? (
                            <img
                                src={preview}
                                alt="Preview"
                                className="w-full rounded-lg border-2 border-gray-300"
                            />
                        ) : (
                            <video
                                src={preview}
                                className="w-full rounded-lg border-2 border-gray-300"
                                controls
                            />
                        )}

                        <button
                            type="button"
                            onClick={() => {
                                setPreview(null);
                                fileInputRef.current.value = '';
                            }}
                            className="absolute top-2 right-2 bg-white rounded-full p-1 shadow-md"
                        >
                            <svg className="w-5 h-5 text-gray-700" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </button>
                    </div>
                ) : (
                    <div className="flex justify-center">
                        <div className="space-y-4">
                            <button
                                type="button"
                                onClick={startCapture}
                                className="block w-full px-4 py-2 bg-blue-600 text-white rounded-lg shadow-md hover:bg-blue-700"
                            >
                                {mediaType === 'image' ? 'Open Camera' : 'Record Video'}
                            </button>

                            <div className="text-center">
                                <span className="text-gray-500">or</span>
                            </div>

                            <label className="block w-full px-4 py-2 bg-gray-200 text-gray-700 rounded-lg shadow-md hover:bg-gray-300 cursor-pointer text-center">
                                Choose File
                                <input
                                    type="file"
                                    ref={fileInputRef}
                                    accept={mediaType === 'image' ? 'image/*' : 'video/*'}
                                    onChange={handleFileChange}
                                    className="hidden"
                                    capture={mediaType === 'image' ? 'environment' : true}
                                />
                            </label>
                        </div>
                    </div>
                )}
            </div>

            {uploading && (
                <div className="mt-4">
                    <div className="w-full bg-gray-200 rounded-full h-2.5">
                        <div
                            className="bg-blue-600 h-2.5 rounded-full"
                            style={{ width: `${uploadProgress}%` }}
                        ></div>
                    </div>
                    <p className="text-sm text-gray-600 mt-2 text-center">
                        {isOffline ? 'Saving locally...' : 'Uploading...'} {uploadProgress}%
                    </p>
                </div>
            )}

            {error && (
                <div className="mt-4 bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-r">
                    <p>{error}</p>
                </div>
            )}

            {isOffline && (
                <div className="mt-4 bg-amber-100 border-l-4 border-amber-500 text-amber-700 p-4 rounded-r">
                    <p className="text-sm">
                        You're offline. Media will be uploaded when you're back online.
                    </p>
                </div>
            )}
        </div>
    );
};

export default MediaUploader;
